/* Global Office */

Office.onReady((info) => {
  if (info.host === Office.HostType.Outlook) {
    const saveBtn = document.getElementById("save-btn") as HTMLButtonElement | null;
    const customTextInput = document.getElementById("custom-text") as HTMLTextAreaElement | null;
    const statusMsg = document.getElementById("status-msg") as HTMLDivElement | null;

    if (saveBtn && customTextInput && statusMsg) {
      // Laad de eventueel eerder opgeslagen tekst in het invoerveld
      customTextInput.value = localStorage.getItem("DeOever_CustomText") || "";

      saveBtn.onclick = () => {
        // Sla de handmatige invoer op in de lokale opslag van de add-in
        localStorage.setItem("DeOever_CustomText", customTextInput.value);
        
        // Toon een kort succesbericht
        statusMsg.style.display = "block";
        setTimeout(() => { 
          statusMsg.style.display = "none"; 
        }, 3000);
      };
    }
  }
});
